async function loadHome(){const s=await api('GET','/api/public/stats');if(s.total_reported!=null){$('s1').textContent=s.total_reported;$('s2').textContent=s.citizen_verified_resolved;$('s3').textContent=s.pending}
 const f=await api('GET','/api/public/feed?limit=3');$('homefeed').innerHTML=(Array.isArray(f)&&f.length)?f.slice(0,3).map(issueHtml).join(''):empty('No public issues yet. Be the first to report one.')}
function empty(m){return `<div class="empty">${ic('flag')}<div>${esc(m)}</div></div>`}
function issueHtml(x){return `<div class="issue"><div class="im">${x.photo?`<img src="${esc(x.photo)}" alt="">`:ic('image')}</div><div class="bd"><div class="row" style="gap:6px"><b>${esc(x.category)}</b>${x.emergency?'<span class="chip r">urgent</span>':''}<span class="chip ${chipFor(x.status)}">${esc(lab(x.status))}</span></div><div class="sm mut">${esc(x.city||'')}${x.state?', '+esc(x.state):''} · ${esc(x.reported)} · ${x.supporters} supporting</div><div class="xs mut">${esc(x.label)}${x.official_ids.length?' · Official ID '+x.official_ids.map(o=>esc(o.ref)).join(', '):''}</div><div class="row" style="margin-top:6px"><button class="btn out sm" onclick="sup(${x.id})">${ic('thumbs-up')}Support</button><button class="btn out sm" onclick="sup(${x.id},'still_exists')">Still exists</button></div></div></div>`}
