const WL=['Photo','Details','Review','Submit'];
function wiz(n){WSTEP=n;$('wiz').innerHTML=WL.map((l,i)=>`<div class="${i+1<n?'d':i+1==n?'c':''}"><i></i>${l}</div>`).join('');['w1','w2','w3'].forEach((id,i)=>$(id).style.display=(n==i+1||(n==4&&id=='w3'))?'':'none')}
window.fillConst=async function(){const st=$('state').value.trim();const r=await api('GET','/api/directory/constituencies?state='+encodeURIComponent(st));$('cstl').innerHTML=((r&&r.items)||[]).map(c=>'<option value="'+esc(c)+'">').join('')};
window.nextW=function(n){if(n==3||n==2)fillConst();if(n==2&&!LL){toast('Tap the map or use GPS first');return}wiz(n);if(n==2)similarCheck()};
window.similarCheck=async function(){const b=$('simbox');if(!b||!LL)return;const r=await api('GET','/api/public/similar?lat='+LL.lat+'&lon='+LL.lon);const it=(r&&r.items)||[];
 b.style.display=it.length?'':'none';b.innerHTML=it.length?`<div class="info bl"><i data-ic="layers"></i><div><b>${it.length} similar open report${it.length>1?'s':''} within 250 m.</b> Support an existing one to add weight, or continue if yours is different.${it.map(x=>`<div class="row sm" style="margin-top:6px"><span class="grow">${esc(x.code)} · ${esc(lab(x.category||'issue'))} · ${x.distance_m} m · ${esc(lab(x.status))}</span><button class="btn out sm" onclick="supportSim(${x.id})">Support</button></div>`).join('')}</div></div>`:'';if(it.length)icons(b)};
window.supportSim=async function(id){if(!T){openLogin();return}const r=await api('POST','/api/complaints/'+id+'/support',{kind:'support'});toast(r.error?r.error:'Thanks, your support is added');if(!r.error)go('nearby')};
let PM=null,PMK=null;
function initPick(){if(!window.L)return;if(!PM){PM=L.map('pickmap',{zoomControl:true}).setView(LL?[LL.lat,LL.lon]:[20.59,78.96],LL?16:5);(LITE()||L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(PM));PM.on('click',e=>setLL(e.latlng.lat,e.latlng.lng))}setTimeout(()=>PM.invalidateSize(),80)}
function setLL(la,lo,acc){LL={lat:la,lon:lo,acc};if(PMK)PMK.setLatLng([la,lo]);else{PMK=L.marker([la,lo],{draggable:true}).addTo(PM);PMK.on('dragend',()=>{const p=PMK.getLatLng();setLL(p.lat,p.lng)})}$('coords').textContent=la.toFixed(5)+', '+lo.toFixed(5)+(acc?' (±'+Math.round(acc)+' m)':'')}
window.gps=function(){navigator.geolocation?navigator.geolocation.getCurrentPosition(p=>{initPick();setLL(p.coords.latitude,p.coords.longitude,p.coords.accuracy);PM.setView([p.coords.latitude,p.coords.longitude],17)},e=>toast('GPS unavailable: '+e.message),{enableHighAccuracy:true,timeout:15000}):toast('GPS not supported')};
$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;IMG=await createImageBitmap(f);const s=Math.min(1,1280/Math.max(IMG.width,IMG.height));const cv=$('cv');cv.width=Math.round(IMG.width*s);cv.height=Math.round(IMG.height*s);RECTS=[];PHOTO=null;draw();$('ed').style.display='';$('dropz').style.display='none';PHASH=dhash(IMG);rebuild()};
function draw(){const cv=$('cv'),c=cv.getContext('2d');c.drawImage(IMG,0,0,cv.width,cv.height);RECTS.forEach(r=>pix(c,r))}
function pix(c,r){const w=Math.abs(r.w),h=Math.abs(r.h);if(w<2||h<2)return;const k=Math.max(6,Math.round(Math.min(w,h)/6));const t=document.createElement('canvas');t.width=Math.max(1,Math.round(w/k));t.height=Math.max(1,Math.round(h/k));t.getContext('2d').drawImage(c.canvas,r.x,r.y,w,h,0,0,t.width,t.height);c.imageSmoothingEnabled=false;c.drawImage(t,0,0,t.width,t.height,r.x,r.y,w,h);c.imageSmoothingEnabled=true}
const cvE=$('cv');const pos=e=>{const b=cvE.getBoundingClientRect();return{x:(e.clientX-b.left)*cvE.width/b.width,y:(e.clientY-b.top)*cvE.height/b.height}};
cvE.onpointerdown=e=>{DRAG=pos(e);cvE.setPointerCapture(e.pointerId)};cvE.onpointermove=e=>{if(!DRAG)return;const p=pos(e);draw();const c=cvE.getContext('2d');c.strokeStyle='#ff9933';c.lineWidth=3;c.strokeRect(DRAG.x,DRAG.y,p.x-DRAG.x,p.y-DRAG.y)};
cvE.onpointerup=e=>{if(!DRAG)return;const p=pos(e);RECTS.push({x:Math.min(DRAG.x,p.x),y:Math.min(DRAG.y,p.y),w:Math.abs(p.x-DRAG.x),h:Math.abs(p.y-DRAG.y)});DRAG=null;draw();rebuild()};
window.undoBlur=()=>{RECTS.pop();draw();rebuild()};
window.autoFaces=async function(){if(!window.FaceDetector){toast('Auto face detection is not available in this browser. Blur by dragging on the photo.');return}const fs=await new FaceDetector().detect(cvE);fs.forEach(f=>RECTS.push({x:f.boundingBox.x,y:f.boundingBox.y,w:f.boundingBox.width,h:f.boundingBox.height}));draw();rebuild();toast(fs.length+' face(s) blurred. Also blur number plates yourself.')};
function rebuild(){cvE.toBlob(b=>{BLOB=b;PHOTO=null},'image/jpeg',LITE()?0.5:0.72)}
async function uploadBlob(b){try{const r=await fetch('/api/upload',{method:'POST',headers:{Authorization:'Bearer '+T},body:await b.arrayBuffer()});return await r.json()}catch(e){return null}}
function dhash(img){const c=document.createElement('canvas');c.width=9;c.height=8;const x=c.getContext('2d');x.drawImage(img,0,0,9,8);const d=x.getImageData(0,0,9,8).data;const g=i=>d[i*4]*.3+d[i*4+1]*.59+d[i*4+2]*.11;let b='';for(let y=0;y<8;y++)for(let i=0;i<8;i++)b+=g(y*9+i)>g(y*9+i+1)?'1':'0';let h='';for(let i=0;i<64;i+=4)h+=parseInt(b.slice(i,i+4),2).toString(16);return h}
window.mic=function(target){const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){toast('Voice input is not supported in this browser');return}const r=new R();r.lang=SPEECH[LG()]||'en-IN';const el=$(typeof target=='string'?target:'desc');r.onresult=e=>{el.value=(el.value+' '+e.results[0][0].transcript).trim()};r.onerror=e=>toast('Voice error: '+e.error);r.start();toast('Listening...')};
window.analyse=async function(){if(!T){openLogin();return}if(BLOB&&!PHOTO){const j=await uploadBlob(BLOB);if(j&&j.url)PHOTO=j.url}
 const d={title:$('title').value.trim()||($('desc').value.trim().slice(0,60)),description:$('desc').value,photo_url:PHOTO?location.origin+PHOTO:null,phash:PHASH,lang:LG(),address:$('addr').value,city:$('city').value,state:$('state').value,pincode:$('pin').value,lat:LL?LL.lat:NaN,lon:LL?LL.lon:NaN,asset_owner:$('owner').value||null,anonymous:$('anon').checked};
 let c;try{c=await api('POST','/api/complaints',d)}catch(e){saveDraft(d);const m=$('msg');m.style.display='flex';m.textContent=t9('offline');return}
 const m=$('msg');if(!c.ok){m.style.display='flex';m.textContent=(c.errors||[c.error||'Error']).join(' ');return}m.style.display='none';CUR=c;const a=c.ai;
 $('aibox').innerHTML=(c.emergency_notice?`<div class="info rd" style="margin-bottom:10px">${ic('siren')}<div><b>${esc(c.emergency_notice)}</b></div></div>`:'')+`<div class="row" style="gap:8px"><span class="chip">${esc(a.category)}</span><span class="chip ${a.safety_risk=='high'?'r':a.safety_risk=='medium'?'o':'g'}">Safety risk: ${esc(a.safety_risk)}</span></div>
  <div class="sm mut" style="margin:10px 0 4px">Confidence ${Math.round(a.confidence*100)}%</div><div class="meter"><i style="width:${a.confidence*100}%"></i></div>
  <div class="sm mut" style="margin:10px 0 4px">Severity</div><span class="dots ${a.severity>=4?'hi':''}">${[1,2,3,4,5].map(i=>`<i class="${i<=a.severity?'on':''}"></i>`).join('')}</span>
  <div class="sm" style="margin-top:10px">Suggested department: <b>${esc(a.suggested_department)}</b></div>${c.duplicate_group?`<div class="info bl sm" style="margin-top:10px">${ic('layers')}<div>Similar report nearby (${Math.round((c.duplicate_probability||0)*100)}% likely the same). Yours is grouped with it and keeps its own reference.</div></div>`:''}
  <div class="xs mut" style="margin-top:8px">${esc(a.engine)}. ${esc(a.notes)}</div>${a.confidence<0.6?'<div class="info" style="margin-top:10px">Low confidence. Please choose the right category below.</div>':''}`;
 const cats=['garbage','drainage','toilet','road','water','electricity','railway','consumer','pension','police','general'];$('catsel').innerHTML=cats.map(x=>`<option ${x==a.category?'selected':''}>${x}</option>`).join('');wiz(3);showRoute()};
async function showRoute(){const r=await api('GET','/api/complaints/'+CUR.id+'/route');$('routebox').innerHTML=r.targets.map(t=>`<div class="rec"><div class="row"><b>${esc(t.platform_id)}</b><span class="chip ${t.level==1?'g':t.level==3?'':'k'}">Level ${t.level}</span></div><div class="sm mut">${esc(t.reason)}${t.validation_errors.length?' · needs: '+esc(t.validation_errors.join(', ')):''}</div></div>`).join('')+(r.needs.length?`<div class="info rd">${esc(r.needs.join(' '))}</div>`:'')+(r.targets.length?'':'<div class="info">No verified official channel matches yet. A verification officer will review.</div>')+`<details><summary>Channels not used and why</summary>${r.rejected.map(x=>`<div class="xs mut">${esc(x[0])}: ${esc(x[1])}</div>`).join('')}</details>`}
