window.submitC=async function(){const r=await api('POST','/api/complaints/'+CUR.id+'/submit',{consent_submit:$('c1').checked,consent_share_personal:$('c2').checked,notify_representative:$('c3').checked,consent_email:$('c4').checked,consent_x:$('c6').checked,reply_to_user:$('c5').checked,constituency:$('cst').value.trim(),company:$('cmp').value.trim()});const m=$('submsg');m.style.display='flex';m.className='info '+(r.ok?'gr':'rd');
 m.innerHTML=r.ok?`<div><b>Done. JANSEVA ID ${esc(CUR.code)}.</b><div class="sm">${r.merged_into?'Merged with '+esc(r.merged_into)+' (already filed).':'Guided channels still need you to submit on the official portal. Nothing shows as registered until a real reference exists.'}</div>${dispHtml(r.email_dispatch)}${r.x_queue?'<div class="sm">X: '+(r.x_queue.ok?'queued for the JANSEVA account (posted when slot is free)':esc(r.x_queue.error))+'</div>':''}<button class="btn sm" style="margin-top:8px" onclick="tweetC()">Post on X (from your account)</button> <button class="btn pri sm" style="margin-top:8px" onclick="go('mine')">Open My Complaints</button></div>`:`<div>${esc(r.error||(r.needs||[]).join(' ')||'Could not submit')}</div>`}
// ---------- drafts ----------
function drafts(){try{return JSON.parse(LS.drafts||'[]')}catch(e){return[]}}
async function saveDraft(d){const l=drafts();const x={...d};if(BLOB)x.photo_data=await new Promise(r=>{const f=new FileReader();f.onload=()=>r(f.result);f.readAsDataURL(BLOB)});l.push(x);try{LS.drafts=JSON.stringify(l)}catch(e){delete x.photo_data;l[l.length-1]=x;LS.drafts=JSON.stringify(l)}toast(t9('offline'))}
async function flushDrafts(){if(!navigator.onLine||!T)return;const l=drafts();if(!l.length)return;const rest=[];for(const d of l){try{let ph=d.photo_url;if(d.photo_data){const j=await uploadBlob(await (await fetch(d.photo_data)).blob());if(j&&j.url)ph=location.origin+j.url}delete d.photo_data;d.photo_url=ph;const c=await api('POST','/api/complaints',d);if(!c.ok&&!c.duplicate_of)rest.push(d)}catch(e){rest.push(d)}}LS.drafts=JSON.stringify(rest);if(rest.length<l.length)toast('Offline drafts sent')}
addEventListener('online',flushDrafts);
