async function load(){$('list').innerHTML='<div class="skel"></div><div class="skel"></div>';const l=await api('GET','/api/complaints');if(!Array.isArray(l)){$('list').innerHTML=`<div class="card empty">${ic('lock')}<div>Please log in to see your complaints.</div><button class="btn pri" style="margin-top:10px" onclick="openLogin()">Login</button></div>`;return}
 if(!l.length){$('list').innerHTML=`<div class="card empty">${ic('camera')}<div>No complaints yet.</div><button class="btn saf" style="margin-top:10px" onclick="go('report')">Report a problem</button></div>`;return}
 let h='';for(const c of l){const d=await api('GET','/api/complaints/'+c.id);const si=stageIdx(c.status);
  h+=`<div class="card"><div class="row"><b>${esc(c.code)}</b><span class="chip ${chipFor(c.status)}">${esc(lab(c.status))}</span>${c.official_basis=='sandbox'?'<span class="chip sandbox">Sandbox, not official</span>':''}${c.emergency?'<span class="chip r">Urgent</span>':''}</div><div style="margin-top:4px">${esc(c.title||c.description.slice(0,60))}</div>
  <div class="seg">${STAGES.map((s,i)=>`<i class="${i<si?'on':i==si?'cur':''}"></i>`).join('')}</div><div class="segl"><span>Reported</span><span>${esc(STG_L[si])}</span><span>Verified</span></div><div class="csum sm mut">${(d.dispatches||[]).filter(x=>x.status=='sent').length} emailed · ${(d.external_records||[]).length} portal records · ${d.timeline.length} updates</div><details class="cx"><summary>Details, officials, timeline</summary>`;
  for(const e of d.external_records){const g=(e.evidence&&e.evidence.guide)||{};h+=`<div class="rec"><div class="row"><span class="chip ${e.mode}">${esc(e.mode)}</span><b>${esc(e.platform_id)}</b><span class="chip k">L${e.level}</span><span class="chip">${esc(lab(e.status))}</span></div><div class="sm mut" style="margin-top:4px">${e.external_ref?'Reference <b>'+esc(e.external_ref)+'</b> ('+esc(e.reference_source)+')':'No reference yet. Not registered.'}</div>`;
   if(e.level>=3&&!e.external_ref)h+=`<details><summary>How to submit officially</summary>${g.portal?`<a class="btn pri sm" href="${esc(g.portal)}" target="_blank" rel="noopener" onclick="return openPortal(this.href)">${ic('globe')}Open official portal</a> <button class="btn out sm" onclick="cpTxt(${e.id})">${ic('copy')}Copy complaint text</button>`:''}<ol class="sm">${(g.steps||[]).map(s=>'<li>'+esc(s)+'</li>').join('')}</ol><pre class="gt" id="gt${e.id}">${esc(g.complaint_text)}</pre><div class="sm mut">You sign in on the official site yourself. JANSEVA never sees your password or OTP and never solves CAPTCHA. This portal cannot be embedded here (it blocks framing), so it opens in a secure browser tab.</div><div class="row"><input class="grow" id="ref${e.id}" placeholder="Reference number from the portal"><button class="btn pri sm" onclick="ref(${c.id},'${e.platform_id}',${e.id})">Save</button></div></details>`;h+='</div>'}
  for(const e of d.external_records)if(e.external_ref&&e.level>=3)h+=`<details><summary>Update from ${esc(e.platform_id)} portal</summary><div class="sm mut">Check your status on the official portal and tell us. Marked as citizen-reported, not verified by the government.</div><div class="row" style="margin-top:6px"><select id="ps${e.id}" class="grow"><option value="in progress">In progress</option><option value="reply received">Reply received</option><option value="closed on portal">Closed on portal</option><option value="rejected on portal">Rejected on portal</option></select></div><input id="pn${e.id}" placeholder="What the portal says (optional)" style="margin-top:6px"><button class="btn pri sm" style="margin-top:6px" onclick="pst(${c.id},'${e.platform_id}',${e.id})">Save update</button></details>`;
  if((d.dispatches||[]).length)h+=`<details><summary>Sent to authorities (${d.dispatches.filter(x=>x.status=='sent').length} of ${d.dispatches.length})</summary>${d.dispatches.map(x=>`<div class="row sm" style="padding:4px 0"><span class="chip k">L${x.level}</span><span class="grow">${esc(x.target_name)}</span><span class="chip ${x.status=='sent'?'g':x.status=='failed'?'r':''}">${x.status=='scheduled'?'due '+esc(String(x.due_at).slice(0,10)):esc(x.status)}</span></div>`).join('')}<div class="sm mut">Emailed means delivered to their inbox, not registered. A reply from the authority is what changes the status.</div></details>`;
  if(d.x_queue)h+=`<div class="sm" style="margin-top:6px">X post: ${esc(d.x_queue.status)}${d.x_queue.tweet_url?' · <a href="'+esc(d.x_queue.tweet_url)+'" target="_blank" rel="noopener">view</a>':''}</div>`;
  h+=`<details><summary>Timeline (${d.timeline.length})</summary><div class="tl">${d.timeline.map(t=>`<div><span class="xs mut">${esc(t.ts.slice(0,16).replace('T',' '))}</span><br>${esc(t.message)}</div>`).join('')}</div></details>`;
  h+='</details>';
  if(['authority_marked_resolved','citizen_verified_resolved','reopened'].includes(c.status))h+=`<div class="info" style="margin-top:8px">${ic('circle-check')}<div><b>Authority says resolved?</b> Check the spot and tell us. Add an after photo if you can.<div class="row" style="margin-top:8px"><input type="file" id="af${c.id}" accept="image/*" class="grow"><button class="btn ok sm" onclick="vf(${c.id},true)">Verified</button><button class="btn red sm" onclick="vf(${c.id},false)">Not resolved</button></div></div></div>`;
  h+=`<div class="row" style="margin-top:10px"><button class="btn out sm" onclick="sy(${c.id})">${ic('refresh-cw')}Sync status</button></div></div>`}
 $('list').innerHTML=h}
