 <div class="card"><h3>${ic('circle-check')}Citizen-verified resolution</h3><div class="row"><b style="font-size:30px;color:var(--green)">${s.resolution_percent_citizen_verified==null?'n/a':s.resolution_percent_citizen_verified+'%'}</b><span class="sm mut">Average hours to verified resolution: ${s.avg_hours_to_verified_resolution==null?'n/a':s.avg_hours_to_verified_resolution} · to acknowledgement: ${s.avg_hours_to_acknowledgement==null?'n/a':s.avg_hours_to_acknowledgement}</span></div></div>
