function applyLD(){const on=LS.ld==='1';document.documentElement.classList.toggle('lite',on);const b=$('ldbtn');if(b)b.classList.toggle('on',on)}
window.LITE=()=>LS.ld==='1'||(navigator.connection&&(navigator.connection.saveData||/2g/.test(navigator.connection.effectiveType||'')));
applyLD();
