const INTRO={en:{t:'Report a public problem. Get it to the right authority.',p:'JANSEVA AI helps any citizen of India report a civic problem and track it until it is really fixed.',s:[['1','Take a photo','Snap the problem. Your location is picked up. Blur faces and plates on your phone.'],['2','AI checks it','It suggests the category and the right office. You confirm. Nothing goes out without your tick.'],['3','Sent with your consent','Official portals, nodal officers by email, your MP, and optional X tags. You choose each one.'],['4','You verify the fix','An authority saying "resolved" is not enough. You confirm, with an after photo.']],n:'Honest by design: "sent" never means "registered". Nothing is called official until an authority replies. Your phone and name are never shown publicly.',go:'Report a problem',skip:'Look around first'},
 hi:{t:'सार्वजनिक समस्या दर्ज करें। सही अधिकारी तक पहुँचाएँ।',p:'JANSEVA AI भारत के किसी भी नागरिक को नागरिक समस्या दर्ज करने और ठीक होने तक ट्रैक करने में मदद करता है।',s:[['1','फोटो लें','समस्या की फोटो खींचें। लोकेशन अपने आप आती है। चेहरे और नंबर प्लेट अपने फोन पर धुंधले करें।'],['2','AI जाँच करता है','श्रेणी और सही दफ़्तर सुझाता है। आप पक्का करते हैं। आपकी मंज़ूरी के बिना कुछ नहीं जाता।'],['3','आपकी सहमति से भेजा जाता है','सरकारी पोर्टल, नोडल अधिकारी को ईमेल, आपके सांसद, और चाहें तो X पर टैग। हर चीज़ आप चुनते हैं।'],['4','समाधान आप जाँचते हैं','अधिकारी का "हल हो गया" कहना काफ़ी नहीं। आप बाद की फोटो के साथ पुष्टि करते हैं।']],n:'ईमानदार तरीका: "भेजा गया" का मतलब "दर्ज हुआ" नहीं है। अधिकारी के जवाब तक कुछ भी आधिकारिक नहीं कहा जाता। आपका फोन और नाम सार्वजनिक नहीं दिखता।',go:'समस्या दर्ज करें',skip:'पहले देख लूँ'}};
let ILG=(LS.jl==='hi')?'hi':'en';
function introRender(){const d=INTRO[ILG];$('introT').textContent=d.t;$('introP').textContent=d.p;$('introN').textContent=d.n;$('introGo').textContent=d.go;$('introSkip').textContent=d.skip;
 $('introS').innerHTML=d.s.map(x=>`<div class="istep"><span class="in">${x[0]}</span><div><b>${esc(x[1])}</b><div class="sm mut">${esc(x[2])}</div></div></div>`).join('')}
